WITH base AS (SELECT *, LENGTH(dept_name) AS dept_name_length FROM departments WHERE dept_name IS NOT NULL), with_last AS (SELECT s.*, top1.employee_job_title FROM base s LEFT JOIN LATERAL (SELECT c.job_title AS employee_job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored AS (SELECT *, ROUND(budget / SUM(budget) OVER (PARTITION BY location, dept_name), 4) AS budget_share, ROW_NUMBER() OVER (PARTITION BY dept_name, employee_job_title ORDER BY dept_name_length, id) AS row_seq, RANK() OVER (PARTITION BY location, employee_job_title ORDER BY budget NULLS FIRST) AS budget_rank, NTILE(3) OVER (PARTITION BY employee_job_title ORDER BY dept_name_length DESC, id) AS dept_name_length_bucket FROM with_last), stats AS (SELECT CASE WHEN budget_share >= 0.69 THEN 'HIGH' ELSE 'LOW' END AS budget_share_tier, COUNT_IF(dept_name = 'Legal') AS legal_events, COUNT(*) FILTER (WHERE dept_name = 'Finance') AS finance_rows, ROUND(SUM(dept_name_length_bucket) / NULLIF(COUNT(CASE WHEN dept_name = 'Finance' THEN 1 END), 0), 2) AS dept_name_length_bucket_per_finance FROM scored GROUP BY CASE WHEN budget_share >= 0.69 THEN 'HIGH' ELSE 'LOW' END) SELECT budget_share_tier, legal_events, finance_rows, dept_name_length_bucket_per_finance FROM stats ORDER BY legal_events DESC;
